				$ret = 4.3026616884253E+303;
			
			return $ret;
		}
		else
			return $exp[$lvl];
	}
	
	// By Jack
	// No weapon
	public function getFist($second = false){
		$item = [
		"type" => 0,
		"item_id" => 0,
		"dmg_min" => 0,
		"dmg_max" => 0,
		"a1" => 0,
		"a2" => 0,
		"a3" => 0,
		"a4" => 0,
		"a5" => 0,
		"a6" => 0,
		"value_silver" => 0,
		"value_mush" => 0,
		"slot" => 0
		];
		
		if(!$second) {
			$item["dmg_min"] = $this->dmg_min;
			$item["dmg_max"] = $this->dmg_max;
			$item["slot"] = 18;
		} else {
			$item["dmg_min"] = $this->sec_dmg_min;
			$item["dmg_max"] = $this->sec_dmg_max;
			$item["slot"] = 19;
		}
		
		return new Item($item);
	}	
}

